namespace RiftReference {
public sealed class SettingsCard : Panel {
 readonly Color marker;
 public SettingsCard(string name,int top,int height,Color accent){Name=name;Left=0;Top=top;Width=760;Height=height;Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;BackColor=Theme.Panel;marker=accent;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using(var pen=new Pen(Theme.Border))using(var path=Round(new Rectangle(0,0,Width-1,Height-1),12)){g.DrawPath(pen,path);}using(var brush=new SolidBrush(marker))g.FillRectangle(brush,0,18,3,34);}
 static GraphicsPath Round(Rectangle box,int radius){var path=new GraphicsPath();int d=radius*2;path.AddArc(box.Left,box.Top,d,d,180,90);path.AddArc(box.Right-d,box.Top,d,d,270,90);path.AddArc(box.Right-d,box.Bottom-d,d,d,0,90);path.AddArc(box.Left,box.Bottom-d,d,d,90,90);path.CloseFigure();return path;}
}

