  Label(visible,"Scoreboard key",376,64,130,24);keys.SetBounds(506,60,220,28);keys.Name="ScoreboardKey";keys.DropDownStyle=ComboBoxStyle.DropDownList;foreach(Keys key in new[]{Keys.Tab,Keys.Space,Keys.Oemtilde,Keys.F1,Keys.F2,Keys.F3,Keys.F4})keys.Items.Add(key);keys.SelectedItem=(Keys)draft.Key;if(keys.SelectedIndex<0)keys.SelectedIndex=0;visible.Controls.Add(keys);
