 SettingsCard Card(string name,int top,int height,string heading,string detail){var card=new SettingsCard(name,top,height,Theme.Accent);var title=new Label{Text=heading,Left=24,Top=17,Width=680,Height=24,Font=new Font("Segoe UI",11,FontStyle.Bold),ForeColor=Theme.Ink};var note=new Label{Text=detail,Left=24,Top=40,Width=690,Height=22,ForeColor=Theme.Muted};card.Controls.AddRange(new Control[]{title,note});Controls.Add(card);return card;}
 static void Label(Control parent,string text,int x,int y,int w,int h){parent.Controls.Add(new Label{Text=text,Left=x,Top=y,Width=w,Height=h,ForeColor=Theme.Ink});}
 static void Check(Control parent,CheckBox box,string text,bool value,int x,int y,int width){box.Text=text;box.Checked=value;box.SetBounds(x,y,width,26);box.ForeColor=Theme.Ink;parent.Controls.Add(box);}
 static void StylePrimary(Button button){button.BackColor=Theme.Accent;button.ForeColor=Theme.Background;button.FlatAppearance.BorderColor=Theme.Accent;}
 void EditLayout(){var current=Commit();using(var editor=new PanelLayoutEditor(data,current))if(editor.ShowDialog(FindForm())==DialogResult.OK){StatsPanel.Copy(editor.Result,draft);PanelSizing.Copy(editor.Result,draft);draft.PanelLayoutVersion=1;draft.BuildPlaced=editor.Result.BuildPlaced;draft.BuffsPlaced=editor.Result.BuffsPlaced;draft.BuildU=editor.Result.BuildU;draft.BuildV=editor.Result.BuildV;draft.BuffsU=editor.Result.BuffsU;draft.BuffsV=editor.Result.BuffsV;purchase.Checked=editor.Result.Purchase;buffs.Checked=editor.Result.Buffs;status.Text="Panel positions and sizes updated. Save preferences to keep them.";}}
 void AlignScoreboard(){using(var form=new ScoreboardAlignment(data,Commit()))if(form.ShowDialog(FindForm())==DialogResult.OK){draft.BoardX=form.Result.BoardX;draft.BoardY=form.Result.BoardY;draft.BoardScale=form.Result.BoardScale;draft.RowStart=form.Result.RowStart;draft.RowGap=form.Result.RowGap;draft.AlliesLeft=form.Result.AlliesLeft;status.Text="Scoreboard alignment updated. Save preferences to keep it.";}}
 void ChooseBuild(){try{var selected=champions.SelectedItem as BuildChoice;if(selected==null)throw new ArgumentException("Select your champion first.");using(var picker=new RecommendationPicker(data,data.Resolve(selected.Id.ToString())))if(picker.ShowDialog(FindForm())==DialogResult.OK)UsePlan(picker.PlanJson);}catch(Exception ex){status.Text=ex.Message;}}
 void UsePlan(string json){string champion,patch;var ids=OverlaySettings.PlanItems(data,json,out champion,out patch);if(Recommendations.Patch(patch)!=Recommendations.Patch(data.Version))throw new ArgumentException("Refresh the build for your current patch.");planIds=new HashSet<int>(ids);draft.PlanPatch=patch;draft.Source="Diamond+ selected build";champions.SelectedItem=champions.Items.Cast<BuildChoice>().First(c=>data.Resolve(c.Id.ToString())==champion);search.Clear();Populate();items.SelectedItem=items.Items.Cast<BuildChoice>().FirstOrDefault(c=>c.Id==ids[0]);status.Text="Selected build loaded. Choose the target item you want to track, then save preferences.";}
 void LoadPlan(){try{using(var dialog=new OpenFileDialog{Filter="Rift loadout (*.json)|*.json"})if(dialog.ShowDialog(FindForm())==DialogResult.OK){if(new FileInfo(dialog.FileName).Length>65536)throw new ArgumentException("Plan is too large.");UsePlan(File.ReadAllText(dialog.FileName,System.Text.Encoding.UTF8));draft.Source="Saved loadout plan";}}catch(Exception ex){status.Text=ex.Message;}}
 void Populate(){var chosen=items.SelectedItem as BuildChoice;items.Items.Clear();foreach(var pair in data.Items.Where(p=>OverlayData.Purchasable(data,Int32.Parse(p.Key))&&(planIds==null||planIds.Contains(Int32.Parse(p.Key)))&&J.S(p.Value,"name").IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0).OrderBy(p=>J.S(p.Value,"name")))items.Items.Add(new BuildChoice(Int32.Parse(pair.Key),J.S(pair.Value,"name")));if(chosen!=null)items.SelectedItem=items.Items.Cast<BuildChoice>().FirstOrDefault(c=>c.Id==chosen.Id);}
 public OverlayOptions Commit(){draft.Enabled=enabled.Checked;draft.GameBar=gameBar.Checked;draft.Gold=gold.Checked;draft.Buffs=buffs.Checked;draft.Purchase=purchase.Checked;draft.Stats=stats.Checked;draft.StatsCspm=cspm.Checked;draft.StatsKp=kp.Checked;draft.StatsCs=cs.Checked;draft.StatsKda=kda.Checked;draft.StatsVision=vision.Checked;draft.Key=(int)(Keys)keys.SelectedItem;var champion=champions.SelectedItem as BuildChoice;var item=items.SelectedItem as BuildChoice;draft.Champion=champion==null?"":data.Resolve(champion.Id.ToString());draft.Target=item==null?0:item.Id;return draft.Copy();}
}

