  releaseCard=Card("ReleaseCard",36,TitleHeight+242,ClientSize.Width-72,190,"RELEASE STATUS","Check for a new verified Rift Ready release.");status.SetBounds(24,76,releaseCard.Width-48,54);status.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;status.ForeColor=Theme.Muted;status.Text=updater.Status;releaseCard.Controls.Add(status);notes.SetBounds(24,130,releaseCard.Width-48,126);notes.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;notes.Multiline=true;notes.ReadOnly=true;notes.ScrollBars=ScrollBars.Vertical;notes.Text=updater.Available==null?"":updater.Available.notes;releaseCard.Controls.Add(notes);
  check.Text="Check for updates";check.SetBounds(36,TitleHeight+468,180,38);check.Anchor=AnchorStyles.Left|AnchorStyles.Bottom;check.Click+=async(s,e)=>await Check();Controls.Add(check);install.Text="Download and install";install.SetBounds(230,TitleHeight+468,210,38);install.Anchor=AnchorStyles.Left|AnchorStyles.Bottom;install.Enabled=updater.Available!=null;install.Click+=async(s,e)=>await Install();Controls.Add(install);footer=new Label{Text="Downloads use HTTPS and are checked against the Rift Ready publisher signature. Your saved preferences are retained.",Left=458,Top=TitleHeight+468,Width=310,Height=54,Anchor=AnchorStyles.Right|AnchorStyles.Bottom,ForeColor=Theme.Muted};Controls.Add(footer);Theme.Apply(this);RefreshReleaseLayout();
 }
 SettingsCard Card(string name,int x,int y,int width,int height,string heading,string detail){var card=new SettingsCard(name,y,height,Theme.Accent){Left=x,Width=width,Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right};card.Controls.Add(new Label{Text=heading,Left=24,Top=17,Width=620,Height=24,Font=new Font("Segoe UI",11,FontStyle.Bold),ForeColor=Theme.Ink});card.Controls.Add(new Label{Text=detail,Left=24,Top=42,Width=620,Height=24,ForeColor=Theme.Ink});Controls.Add(card);return card;}
 async Task Check(){check.Enabled=false;status.Text="Checking for updates…";try{await checkUpdates();if(IsDisposed)return;status.Text=updater.Status;notes.Text=updater.Available==null?"":updater.Available.notes;install.Enabled=updater.Available!=null;RefreshReleaseLayout();}finally{if(!IsDisposed)check.Enabled=true;}}
 async Task Install(){if(!canUpdate()){status.Text="Finish champion select or your match before updating.";return;}install.Enabled=false;check.Enabled=false;try{status.Text="Downloading and verifying the release…";string file=await updater.Prepare();if(IsDisposed)return;if(!canUpdate()){status.Text="A match started. Install after it finishes.";return;}updater.Launch(file);InstallLaunched=true;DialogResult=DialogResult.OK;}catch(Exception ex){if(!IsDisposed)status.Text=ex.Message;}finally{if(!IsDisposed){check.Enabled=true;install.Enabled=updater.Available!=null;}}}
 public void CaptureImage(string path){StartPosition=FormStartPosition.Manual;Location=new Point(-30000,-30000);Show();Application.DoEvents();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(Point.Empty,Size));image.Save(path);}Hide();}
 void RefreshReleaseLayout(){bool expanded=updater.Available!=null&&!String.IsNullOrWhiteSpace(notes.Text);ClientSize=new Size(ClientSize.Width,expanded?650:560);releaseCard.Height=expanded?286:190;notes.Visible=expanded;int top=TitleHeight+(expanded?548:468);check.Top=top;install.Top=top;footer.Top=top;if(install.Enabled)StylePrimary(install);else{install.BackColor=Theme.Panel;install.ForeColor=Theme.Muted;install.FlatAppearance.BorderColor=Theme.Border;}}
 static void StylePrimary(Button button){button.BackColor=Theme.Accent;button.ForeColor=Theme.Background;button.FlatAppearance.BorderColor=Theme.Accent;}
